using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns the list of commands supported by the bot for the given user scope and language; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.BotCommands> GetCommandsAsync(BotCommandScope scope = default, string languageCode = default)
    {

           using var activity =  StartCallActivity("GetCommandsAsync", typeof(GetCommands).FullName ?? "GetCommandsAsync");

           try
           {
             return client.GetCommandsAsync(scope, languageCode);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
